328	/// Which outbound-migration authorization path the wallet should use for a DID.
329	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
330	#[serde(rename_all = "snake_case")]
331	pub enum MigrationPath {
332	    /// The wallet holds an authorized rotation key and can self-sign the PLC op.
333	    SelfSigned,
334	    /// The wallet does not hold an authorized rotation key; use the PDS-signed interop path.
335	    Interop,
336	    /// The wallet cannot safely choose a path (for example, plc.directory is unreachable).
337	    CannotDetermine,
338	}
339	
340	/// Result of deciding which outbound-migration path applies to a DID.
341	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
342	#[serde(rename_all = "camelCase")]
343	pub struct MigrationPathDecision {
344	    pub path: MigrationPath,
345	    /// The wallet's per-DID device key, when available.
346	    pub device_key_id: Option<String>,
347	    /// Index of the device key in the DID's current rotationKeys, if present.
348	    pub rotation_key_index: Option<usize>,
349	    /// Human-readable explanation for UI/orchestrator logging.
350	    pub reason: String,
351	}
352	
353	// ── Pure inputs to the guard ─────────────────────────────────────────────────
354	
355	/// The facts the strict pre-sign guard needs to decide whether a proposed migration
356	/// operation is safe to sign. Deliberately flattened to plain strings/vecs so the
357	/// guard is a pure, trivially testable function.
358	#[derive(Debug, Clone)]
359	pub struct MigrationInputs {
360	    /// The wallet's per-DID device key (`did:key:z...`). Must remain at rotationKeys[0].
361	    pub device_key_id: String,
362	    /// The DID's CURRENT rotation keys (from the latest audit-log op).
363	    pub current_rotation_keys: Vec<String>,
364	    /// The DID's CURRENT alsoKnownAs (handle URIs) — a migration must preserve these.
365	    pub current_also_known_as: Vec<String>,
366	    /// The rotation keys the DESTINATION PDS recommended — the allowlist for keys
367	    /// permitted beyond the device key at [0].
368	    pub recommended_rotation_keys: Vec<String>,
369	    /// The rotation keys we intend to put in the op (device key at [0] + recommended).
370	    pub proposed_rotation_keys: Vec<String>,
371	    /// The alsoKnownAs we intend to put in the op.
372	    pub proposed_also_known_as: Vec<String>,
373	    /// The service ids we intend to put in the op's `services` map.
374	    pub proposed_service_ids: Vec<String>,
375	}
376	
377	// ── The strict pre-sign guard (STRICT ALLOWLIST) ─────────────────────────────
378	
379	/// Reject the proposed migration operation unless it satisfies the strict allowlist.
380	///
381	/// This is the security core of the self-signed migration leg. The device key can
382	/// technically sign anything, so safety comes entirely from validating the INPUTS
383	/// before a signature is ever produced. The policy is a strict allowlist: the op must
384	/// make ONLY the changes a migration is supposed to make, and nothing else, or we
385	/// abort.
386	///
387	/// Return `Ok(())` if every rule holds. Otherwise return the most specific error:
388	/// - `MigrateError::WalletNotAuthorized` when the wallet holds no authorized key for
389	///   the DID (device key is not among `current_rotation_keys`) — the caller will
390	///   defer to the PDS-signed interop path.
391	/// - `MigrateError::GuardRejected { reason }` for any other violation, with a short
392	///   human-readable `reason`.
393	///
394	/// The rules the strict allowlist must enforce:
395	///  1. Sovereignty: `proposed_rotation_keys[0]` equals `device_key_id`.
396	///  2. Authorization: `device_key_id` is present in `current_rotation_keys`
397	///     (otherwise → `WalletNotAuthorized`).
398	///  3. Key allowlist: every proposed rotation key AFTER index 0 appears in
399	///     `recommended_rotation_keys` (no smuggled keys).
400	///  4. Handle preservation: `proposed_also_known_as` equals `current_also_known_as`.
401	///  5. Service allowlist: the proposed op touches ONLY the atproto PDS service —
402	///     `proposed_service_ids` is exactly `[ATPROTO_PDS_SERVICE_ID]`.
403	pub fn guard_migration_op(inputs: &MigrationInputs) -> Result<(), MigrateError> {
404	    // Rule 2 (authorization): the wallet must currently hold an authorized key for
405	    // this DID, or it cannot self-sign — the caller falls back to the interop path.
406	    // Checked first so the distinct `WalletNotAuthorized` signal wins over any
407	    // proposed-op quibble.
408	    if !inputs.current_rotation_keys.contains(&inputs.device_key_id) {
409	        return Err(MigrateError::WalletNotAuthorized);
410	    }
411	
412	    // Rule 1 (sovereignty): the device key must remain at rotationKeys[0].
413	    if inputs.proposed_rotation_keys.first() != Some(&inputs.device_key_id) {
414	        return Err(MigrateError::GuardRejected {
415	            reason: format!(
416	                "device key must be rotationKeys[0]; found {:?}",
417	                inputs.proposed_rotation_keys.first()
418	            ),
419	        });
420	    }
421	
422	    // Rule 3 (key allowlist): every proposed rotation key after [0] must be one the
423	    // destination recommended — no smuggled keys.
424	    for key in inputs.proposed_rotation_keys.iter().skip(1) {
425	        if !inputs.recommended_rotation_keys.contains(key) {
426	            return Err(MigrateError::GuardRejected {
427	                reason: format!("rotation key not recommended by destination: {key}"),
428	            });
429	        }
430	    }
431	
432	    // Rule 4 (handle preservation): a migration must not alter alsoKnownAs.
433	    if inputs.proposed_also_known_as != inputs.current_also_known_as {
434	        return Err(MigrateError::GuardRejected {
435	            reason: "alsoKnownAs (handle) must be preserved across migration".to_string(),
436	        });
437	    }
438	
439	    // Rule 5 (service allowlist): the op may touch only the atproto PDS service.
440	    if inputs.proposed_service_ids.len() != 1
441	        || inputs.proposed_service_ids.first().map(String::as_str) != Some(ATPROTO_PDS_SERVICE_ID)
442	    {
443	        return Err(MigrateError::GuardRejected {
444	            reason: format!(
445	                "migration may only set the '{ATPROTO_PDS_SERVICE_ID}' service; found {:?}",
446	                inputs.proposed_service_ids
447	            ),
448	        });
449	    }
450	
451	    Ok(())
452	}
453	
454	// ── Current-state extraction from the audit log ──────────────────────────────
455	
456	/// The slice of current DID state the migration build needs, derived from the latest
457	/// non-nullified audit-log operation.
458	#[derive(Debug, Clone)]
459	pub(crate) struct CurrentState {
460	    /// CID of the latest op — becomes the new op's `prev`.
461	    pub prev_cid: String,
462	    /// Current rotation keys (for authorization + diff).
463	    pub rotation_keys: Vec<String>,
464	    /// Current alsoKnownAs (preserved into the new op).
465	    pub also_known_as: Vec<String>,
466	    /// Current atproto_pds endpoint, if present (for the diff's `old_endpoint`).
467	    pub pds_endpoint: Option<String>,
468	}
469	
470	/// Read the resulting DID state from the latest non-nullified audit-log entry.
471	///
472	/// A PLC operation's JSON encodes the DID's state AFTER it is applied, so the newest
473	/// entry's `operation` object is the current state. We read fields defensively; an
474	/// empty log or a missing `prev`-able CID is an error (a genesis-only DID that the
475	/// wallet controls still has a CID to chain against).
476	pub(crate) fn latest_op_state(audit_log: &[AuditEntry]) -> Result<CurrentState, MigrateError> {
477	    let latest = audit_log
478	        .iter()
479	        .rev()
480	        .find(|e| !e.nullified)
481	        .ok_or_else(|| MigrateError::InvalidAuditLog {
482	            message: "audit log is empty or fully nullified".to_string(),
483	        })?;
484	
485	    let op = &latest.operation;
486	
487	    // Parse the required arrays strictly: a malformed or missing `rotationKeys` /
488	    // `alsoKnownAs` must be an error, never a silently-truncated `[]`. Truncating
489	    // `alsoKnownAs` to `[]` would let the build "preserve" an empty handle set and
490	    // sign a handle-removing op that the guard's `proposed == current` check misses.
491	    let rotation_keys = string_array_field(op, "rotationKeys")?;
492	    if rotation_keys.is_empty() {
493	        return Err(MigrateError::InvalidAuditLog {
494	            message: "operation.rotationKeys is empty".to_string(),
495	        });
496	    }
497	    let also_known_as = string_array_field(op, "alsoKnownAs")?;
498	
499	    let pds_endpoint = op
500	        .get("services")
501	        .and_then(|s| s.get(ATPROTO_PDS_SERVICE_ID))
502	        .and_then(|svc| svc.get("endpoint"))
503	        .and_then(|e| e.as_str())
504	        .map(String::from);
505	
506	    Ok(CurrentState {
507	        prev_cid: latest.cid.clone(),
508	        rotation_keys,
509	        also_known_as,
510	        pds_endpoint,
511	    })
512	}
513	
514	/// Parse a required string-array field from a PLC operation, rejecting a missing
515	/// field, a non-array value, or any non-string element. This keeps malformed
516	/// audit-log state from being silently coerced into a value we would then sign.
517	fn string_array_field(op: &serde_json::Value, field: &str) -> Result<Vec<String>, MigrateError> {
518	    let arr =
519	        op.get(field)
520	            .and_then(|v| v.as_array())
521	            .ok_or_else(|| MigrateError::InvalidAuditLog {
522	                message: format!("operation.{field} is missing or not an array"),
523	            })?;
524	
525	    arr.iter()
526	        .enumerate()
527	        .map(|(idx, value)| {
528	            value
529	                .as_str()
530	                .map(String::from)
531	                .ok_or_else(|| MigrateError::InvalidAuditLog {
532	                    message: format!("operation.{field}[{idx}] is not a string"),
533	                })
534	        })
535	        .collect()
536	}
537	
538	/// Read current rotation keys from the latest non-nullified PLC audit-log entry.
539	///
540	/// Unlike `pds_client::rotation_keys_from_audit_log`, this helper is strict: malformed
541	/// logs are an error so path detection can fail closed as `CannotDetermine` instead
542	/// of silently picking the interop path from an accidental empty key set.
543	pub(crate) fn current_rotation_keys_from_audit_log(
544	    raw_json: &str,
545	) -> Result<Vec<String>, MigrateError> {
546	    let audit_log =
547	        crypto::parse_audit_log(raw_json).map_err(|e| MigrateError::InvalidAuditLog {
548	            message: format!("failed to parse audit log: {e}"),
549	        })?;
550	    let latest = audit_log
551	        .iter()
552	        .rev()
553	        .find(|e| !e.nullified)
554	        .ok_or_else(|| MigrateError::InvalidAuditLog {
555	            message: "audit log is empty or fully nullified".to_string(),
556	        })?;
557	    let rotation_keys = string_array_field(&latest.operation, "rotationKeys")?;
558	    if rotation_keys.is_empty() {
559	        return Err(MigrateError::InvalidAuditLog {
560	            message: "operation.rotationKeys is empty".to_string(),
561	        });
562	    }
563	    Ok(rotation_keys)
564	}
