28	  let loading = $state(true);
29	  let loadError = $state<string | null>(null);
30	  // Whether the on-mount load failure is terminal (no retry offered). CodeRabbit fix:
31	  // persist this alongside the message so the Retry button can be hidden/disabled.
32	  let loadErrorIsTerminal = $state(false);
33	  let signedOp = $state<SignedMigrationOp | null>(null);
34	
35	  let submitting = $state(false);
