55	  // either the wallet/state isn't authorized to proceed, or the identity/migration
56	  // session itself is gone, so hammering Retry would just fail the same way again.
57	  const TERMINAL_CODES = new Set([
58	    'WALLET_NOT_AUTHORIZED',
59	    'GUARD_REJECTED',
60	    'IDENTITY_NOT_FOUND',
61	    'MIGRATION_NOT_READY',
62	    'DESTINATION_CONFLICT',
63	    'INVALID_RECOMMENDED_CREDENTIALS',
64	    'INVALID_AUDIT_LOG',
65	  ]);
66	
67	  function describeError(raw: unknown): { message: string; terminal: boolean } {
68	    if (isCodedError(raw)) {
69	      const err = raw as MigrationError | MigrateError;
70	      const terminal = TERMINAL_CODES.has(err.code);
71	      switch (err.code) {
72	        case 'WALLET_NOT_AUTHORIZED':
73	          return {
74	            message: 'Your device key is not authorized to sign for this identity.',
75	            terminal: true,
76	          };
77	        case 'GUARD_REJECTED':
78	          return {
79	            message: `This operation was rejected for safety: ${('reason' in err && err.reason) || 'unexpected change'}.`,
80	            terminal: true,
81	          };
82	        case 'INVALID_RECOMMENDED_CREDENTIALS':
83	        case 'INVALID_AUDIT_LOG':
84	          return { message: `Couldn't build the migration operation (${err.code}).`, terminal: true };
85	        case 'SIGNING_FAILED':
86	          return { message: 'Signing failed. Please try again.', terminal: false };
87	        case 'PLC_DIRECTORY_ERROR':
88	          return { message: 'The PLC directory rejected the operation. Please try again.', terminal: false };
89	        case 'NETWORK_ERROR':
90	          return { message: 'Network error. Check your connection and try again.', terminal: false };
91	        case 'IDENTITY_NOT_FOUND':
92	          return { message: 'This identity could not be found.', terminal: true };
93	        case 'MIGRATION_NOT_READY':
94	          return { message: 'Migration is not ready yet. Please restart the migration flow.', terminal: true };
95	        case 'DESTINATION_CONFLICT':
96	          return { message: 'The destination account conflicts with this identity.', terminal: true };
97	        case 'DESTINATION_UNREACHABLE':
98	          return { message: "Couldn't reach the destination PDS.", terminal: false };
99	        case 'ACTIVATION_FAILED':
100	          return { message: 'Activating your new account failed. Please try again.', terminal: false };
101	        case 'SOVEREIGN_LOGIN_FAILED':
102	          return { message: 'Securing your new session failed. Your old account is untouched — please try again.', terminal: false };
103	        case 'SESSION_PERSIST_FAILED':
104	          return { message: "Couldn't save your new session. Your old account is untouched — please try again.", terminal: false };
105	        case 'DEACTIVATION_FAILED':
106	          return { message: 'Deactivating your old account failed. Please try again.', terminal: false };
107	        case 'SOURCE_AUTH_FAILED':
108	          return { message: 'Your source-PDS session expired. Please restart the migration flow.', terminal: true };
109	        default:
110	          return { message: `Something went wrong (${err.code}).`, terminal };
111	      }
112	    }
113	    return { message: 'Something went wrong. Please try again.', terminal: false };
114	  }
115	
116	  async function loadOp() {
117	    loading = true;
118	    loadError = null;
119	    loadErrorIsTerminal = false;
120	    try {
121	      await armIdentityLeg(did);
122	      signedOp = await buildMigrationOp(did);
123	    } catch (raw: unknown) {
124	      console.error('Migration review load failed:', raw);
125	      const described = describeError(raw);
126	      loadError = described.message;
127	      loadErrorIsTerminal = described.terminal;
128	    } finally {
129	      loading = false;
130	    }
131	  }
132	
133	  async function approve() {
134	    error = null;
135	    errorIsTerminal = false;
136	
137	    try {
138	      await authenticateBiometric('Approve the identity change to migrate your account');
