1	import { invoke } from '@tauri-apps/api/core';
2	import type { ClaimResult, OpDiff } from './claim';
3	
4	// ── did:web migration document ────────────────────────────────────────────────
5	
6	export type DidWebMigrationDocument = {
7	  documentText: string;
8	  deviceKey: string;
9	  repoKey: string;
10	  pdsEndpoint: string;
11	};
12	
13	/** Compose the reviewed did:web update for an armed migration identity leg. */
14	export const buildDidWebMigrationDocument = (did: string): Promise<DidWebMigrationDocument> =>
15	  invoke('build_did_web_migration_document_cmd', { did });
16	
17	/** Verify and adopt the published did:web migration document. */
18	export const submitDidWebMigrationDocument = (
19	  did: string,
20	  documentText: string,
21	  enableManagedHosting: boolean,
22	): Promise<ClaimResult> =>
23	  invoke('submit_did_web_migration_document_cmd', { did, documentText, enableManagedHosting });
24	
25	// ── migrate (self-signed identity leg) ────────────────────────────────────────
26	
27	/**
28	 * Error returned by the self-signed migration identity-leg commands.
29	 * Matches MigrateError enum in migrate.rs with #[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")].
30	 *
31	 * WALLET_NOT_AUTHORIZED is the signal to fall back to the PDS-signed interop path:
32	 * the wallet holds no authorized key for this DID, so it cannot self-sign.
33	 */
34	export type MigrateError =
35	  | { code: 'WALLET_NOT_AUTHORIZED' }
36	  | { code: 'GUARD_REJECTED'; reason: string }
37	  | { code: 'INVALID_RECOMMENDED_CREDENTIALS'; message: string }
38	  | { code: 'INVALID_AUDIT_LOG'; message: string }
39	  | { code: 'SIGNING_FAILED'; message: string }
40	  | { code: 'PLC_DIRECTORY_ERROR'; message: string }
41	  | { code: 'NETWORK_ERROR'; message: string }
42	  | { code: 'IDENTITY_NOT_FOUND'; message: string }
43	  | { code: 'MIGRATION_NOT_READY'; message: string };
44	
45	/**
46	 * A locally-built, device-key-signed migration operation ready for review + submission.
47	 * Matches SignedMigrationOp struct in migrate.rs with #[serde(rename_all = "camelCase")].
48	 */
49	export interface SignedMigrationOp {
50	  /** Human-readable diff: the atproto_pds endpoint change plus the rotation-key swap. */
51	  diff: OpDiff;
52	  /** The signed PLC operation JSON, ready to POST to plc.directory. */
53	  signedOp: Record<string, unknown>;
54	}
55	
56	export type MigrationPath = 'self_signed' | 'interop' | 'cannot_determine';
57	
