/// and the lost-response reconciliation path — both need the DID's post-migration
/// state cached identically.
async fn refresh_migration_cache(
    pds_client: &PdsClient,
    did: &str,
) -> Result<ClaimResult, MigrateError> {
    let store = IdentityStore;

    let updated_log =
        pds_client
            .fetch_audit_log(did)
            .await
            .map_err(|e| MigrateError::NetworkError {
                message: format!("failed to fetch updated audit log: {e}"),
